# 149: Hypertensive emergencies & urgencies
kps += [
  {"id":"htn-emergency-d1","topic":"Hypertensive emergencies & urgencies","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What distinguishes a hypertensive emergency from a hypertensive urgency?","answer":"Hypertensive emergency: severe BP elevation (>180/120 mmHg) with evidence of acute target organ damage (encephalopathy, ICH, ACS, acute HF, aortic dissection, eclampsia); urgency: severe BP elevation without acute target organ damage.","rationale":"The presence or absence of end-organ damage, not BP level alone, determines the urgency of treatment and the required setting (ICU vs outpatient).","bloom":"recall","source":[{"book":"Society Guideline: Guideline   JNC7 2003 Hypertension Full Report","page":70}],"confusable_with":"assuming BP level alone determines emergency classification"},
  {"id":"htn-emergency-d2","topic":"Hypertensive emergencies & urgencies","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What is the recommended initial goal for BP reduction in hypertensive emergencies and what is the timeline?","answer":"Reduce mean arterial BP by no more than 25% within the first hour, then to 160/100-110 mmHg over the next 2-6 hours; avoid overcorrection to prevent ischemia.","rationale":"Autoregulation is reset in chronic hypertension; rapid BP lowering to normal levels can cause cerebral, coronary, or renal hypoperfusion in organs dependent on higher pressures.","bloom":"apply","source":[{"book":"Society Guideline: Guideline   JNC7 2003 Hypertension Full Report","page":70}],"confusable_with":"normalizing BP immediately in hypertensive emergencies (risks ischemia from loss of autoregulation)"},
  {"id":"htn-emergency-d3","topic":"Hypertensive emergencies & urgencies","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"Why is short-acting nifedipine specifically contraindicated in hypertensive emergencies?","answer":"Short-acting nifedipine causes uncontrolled, precipitous BP reduction with reflex tachycardia, increasing risk of MI and stroke from hypoperfusion; it is no longer acceptable for initial treatment of hypertensive emergencies or urgencies.","rationale":"The unpredictable and excessive BP drop from sublingual short-acting nifedipine can cause ischemic events, particularly in patients with established atherosclerotic disease.","bloom":"apply","source":[{"book":"Society Guideline: Guideline   JNC7 2003 Hypertension Full Report","page":70}],"confusable_with":"long-acting nifedipine/amlodipine (safe for chronic hypertension, not acute emergency use)"},
  {"id":"htn-emergency-d4","topic":"Hypertensive emergencies & urgencies","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What is the long-term prognosis of patients presenting with hypertensive urgencies or emergencies?","answer":"Unfavorable; 57.5% of patients with severely elevated BP had hypertensive emergencies; median survival was only 14 days in some retrospective studies; 1-2% of hypertensives will experience a hypertensive crisis in their lifetime.","rationale":"Hypertensive emergencies reflect severe end-organ damage and indicate years of poorly controlled hypertension; despite BP control, underlying organ damage determines long-term prognosis.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypertensive Urgency and Emergency","page":6}],"confusable_with":"assuming successful BP control restores full prognosis (chronic end-organ damage persists)"},
  {"id":"htn-emergency-d5","topic":"Hypertensive emergencies & urgencies","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What are common precipitants of acute hypertensive urgencies that differ from emergencies in terms of treatment approach?","answer":"Nonadherence to antihypertensives, sympathomimetic use, thyroid dysfunction, pain, and anxiety; treatment focuses on oral medications, BP monitoring, and reliable primary care follow-up rather than IV agents.","rationale":"Urgencies lack acute end-organ damage; oral therapy with close follow-up addresses the cause without the risk of over-rapid BP reduction from parenteral agents.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypertensive Urgency and Emergency","page":2}],"confusable_with":"treating urgencies with IV labetalol or nicardipine (IV agents are reserved for true emergencies with end-organ damage)"},
  {"id":"htn-emergency-d6","topic":"Hypertensive emergencies & urgencies","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"A pheochromocytoma patient presents with severe hypertension. What adrenergic mechanism causes the crisis and which drug class must be given first?","answer":"Catecholamine surge activates alpha-1 receptors causing peripheral vasoconstriction; alpha-blocker (phentolamine, phenoxybenzamine) must be given before any beta-blocker to prevent paradoxical hypertensive crisis from unopposed alpha stimulation.","rationale":"Beta-blockade without prior alpha-blockade in pheochromocytoma removes the vasodilatory beta-2 effect while leaving alpha-1 vasoconstriction unopposed, worsening hypertension.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":400}],"confusable_with":"starting beta-blocker first for tachycardia (causes paradoxical BP rise in pheochromocytoma)"}
]

kps.append({"_type":"illness_script","topic":"Hypertensive emergencies & urgencies","discipline":"medicine","enabling_conditions":"Uncontrolled/untreated hypertension, medication nonadherence, cocaine/amphetamine use, renal artery stenosis, pheochromocytoma, eclampsia","pathophysiology":"Abrupt rise in systemic vascular resistance overwhelms autoregulatory capacity; endothelial injury and fibrinoid necrosis cause end-organ ischemia","time_course":"Emergency: acute target organ damage within hours; urgency: elevated BP without acute damage, managed over hours to days","key_features":"BP >180/120 mmHg; neurologic changes (encephalopathy, headache), chest pain (ACS/dissection), pulmonary edema, retinal hemorrhages, rising creatinine","consequence_if_missed":"Stroke, acute MI, aortic dissection, hypertensive encephalopathy, eclampsia-related fetal/maternal death if untreated"})

# 150: Hyperthyroidism
kps += [
  {"id":"hyperthyroidism-d1","topic":"Hyperthyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What is the primary treatment for Graves' disease and why is surgery not the first choice?","answer":"Antithyroid drugs (methimazole, PTU) or radioactive iodine are first-line for Graves' disease; surgery (subtotal thyroidectomy) is typically reserved for large toxic multinodular goiters or solitary toxic adenomas, or for patients failing or refusing medical therapy.","rationale":"Graves' disease responds to antithyroid drugs that block thyroid hormone synthesis; radioiodine ablates the hyperactive gland; surgery carries risks of recurrent laryngeal nerve injury and permanent hypoparathyroidism.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":1226}],"confusable_with":"toxic multinodular goiter (surgical treatment preferred; different from Graves' autoimmune etiology)"},
  {"id":"hyperthyroidism-d2","topic":"Hyperthyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What preoperative requirement must be met before elective thyroidectomy or other elective surgery in a hyperthyroid patient?","answer":"Elective surgery should be postponed until the patient is clinically and chemically euthyroid, with normal T3 and T4 concentrations (may take weeks of antithyroid therapy).","rationale":"Uncontrolled hyperthyroidism increases perioperative risk of thyroid storm, which carries high mortality; achieving euthyroid state normalizes metabolic rate and cardiovascular function.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":1226}],"confusable_with":"proceeding with urgently needed surgery without first achieving euthyroid state (requires modified preparation protocol with beta-blockers and potassium iodide)"},
  {"id":"hyperthyroidism-d3","topic":"Hyperthyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What is thyroid storm, and how does it differ from malignant hyperthermia perioperatively?","answer":"Thyroid storm: extreme hyperthyroidism with fever, tachycardia, altered mental status; onset 6-24h post-surgery; unlike MH, NOT associated with muscle rigidity, elevated CK, or marked metabolic/lactic acidosis.","rationale":"Thyroid storm and MH both cause hyperthermia intraoperatively but differ mechanistically; MH involves pathologic calcium release from sarcoplasmic reticulum causing muscle rigidity and metabolic acidosis.","bloom":"analyze","source":[{"book":"Morgan & Mikhail","page":1227}],"confusable_with":"malignant hyperthermia (muscle rigidity and markedly elevated CK are key distinguishing features)"},
  {"id":"hyperthyroidism-d4","topic":"Hyperthyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"TSH and thyroid hormone testing: when should TSH alone be inadequate for inpatient evaluation?","answer":"If thyroidal illness is suspected in inpatients, TSH alone is inadequate; add free T4 and T3 since TSH reflects changes over 4-6 weeks and may lag; undetectable TSH (<0.01) suggests true hyperthyroidism.","rationale":"Acute illness alters TSH independently of true thyroid disease (euthyroid sick syndrome); a full panel (TSH + FT4 + T3) is needed when thyroid disease is clinically suspected.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":189}],"confusable_with":"euthyroid sick syndrome (low TSH from non-thyroidal illness; FT4 normal or low distinguishes it from true hyperthyroidism)"},
  {"id":"hyperthyroidism-d5","topic":"Hyperthyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"T4 is the predominant thyroid hormone secreted, but T3 is more potent. How is most circulating T3 produced?","answer":"Most circulating T3 is formed peripherally from conversion of T4 to T3 by tissue deiodinases; T3 is less protein-bound and more potent than T4.","rationale":"Peripheral conversion of T4 to T3 is regulated by illness and medications; drugs like amiodarone, propylthiouracil, and beta-blockers inhibit this conversion, acutely lowering T3 levels.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":1225}],"confusable_with":"T3 as the directly secreted product (T3 is secreted but most circulating T3 comes from peripheral T4 conversion)"},
  {"id":"hyperthyroidism-d6","topic":"Hyperthyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What is the risk of giving beta-blockers to a patient with pheochromocytoma presenting with tachycardia and what does this share with thyroid storm management?","answer":"In pheochromocytoma, beta-blockers without prior alpha-blockade cause paradoxical hypertension; in thyroid storm, beta-blockers (propranolol) are used to control tachycardia and block peripheral T4-to-T3 conversion -- but only after ensuring no pheochromocytoma.","rationale":"Both conditions present with catecholamine-mediated tachycardia; beta-blockade is useful in thyroid storm (and blocks T4-to-T3 conversion) but dangerous in pheochromocytoma without alpha-blockade.","bloom":"analyze","source":[{"book":"Morgan & Mikhail","page":1226}],"confusable_with":"initiating beta-blockers as primary treatment without considering underlying cause of thyrotoxicosis"}
]

kps.append({"_type":"illness_script","topic":"Hyperthyroidism","discipline":"medicine","enabling_conditions":"Graves' disease (autoimmune TSH-receptor antibody), toxic multinodular goiter, thyroid adenoma, amiodarone, excess exogenous thyroid hormone","pathophysiology":"Excess T3/T4 increases metabolic rate, beta-adrenergic sensitivity, protein catabolism, and heat production; cardiac effects include tachycardia, AF, and high-output state","time_course":"Subclinical (low TSH, normal T3/T4) can persist years; thyroid storm is acute (precipitated by surgery, infection, radioiodine in unprepared patient)","key_features":"Heat intolerance, weight loss, tachycardia/AF, tremor, exophthalmos (Graves'), low TSH with elevated FT4/T3","consequence_if_missed":"Thyroid storm (mortality 10-30%), perioperative cardiac crisis, AF with stroke risk"})

# 151: Hypocalcemia
kps += [
  {"id":"hypocalcemia-d1","topic":"Hypocalcemia","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"How does acidosis affect ionized calcium levels and what is the clinical implication perioperatively?","answer":"Acidosis reduces calcium binding to albumin, increasing ionized calcium; alkalosis (hyperventilation) increases albumin binding, reducing ionized calcium -- perioperative hyperventilation can precipitate symptomatic hypocalcemia.","rationale":"The calcium-albumin binding is pH-dependent; alkalosis shifts equilibrium toward protein-bound calcium, lowering the physiologically active ionized fraction.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":6}],"confusable_with":"total calcium as a reliable guide (ionized calcium is the clinically relevant fraction; total calcium requires albumin correction)"},
  {"id":"hypocalcemia-d2","topic":"Hypocalcemia","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Citrate toxicity during massive blood transfusion can cause clinically important hypocalcemia. When does this typically occur and how is it treated?","answer":"Clinically important hypocalcemia from citrate binding of calcium occurs when transfusion rate exceeds 1 unit per 5 minutes; hepatic citrate metabolism is the primary clearance mechanism; treat with IV calcium salts only when measured hypocalcemia is confirmed.","rationale":"Citrate in banked blood chelates ionized calcium; the liver normally metabolizes citrate rapidly, but at high transfusion rates or in liver failure, citrate accumulates and causes cardiac depression.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":1968}],"confusable_with":"routinely giving IV calcium with every transfusion (indicated only for measured hypocalcemia, not prophylactically in most patients)"},
  {"id":"hypocalcemia-d3","topic":"Hypocalcemia","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"How does CKD cause hypocalcemia through impaired vitamin D metabolism?","answer":"CKD impairs renal 1-alpha-hydroxylase activity, reducing conversion of 25-OH vitamin D to active calcitriol (1,25-dihydroxyvitamin D); reduced calcitriol decreases GI calcium absorption; also impaired phosphate excretion raises phosphate, which binds calcium.","rationale":"The kidney is essential for vitamin D activation; without calcitriol, intestinal calcium absorption is impaired; hyperphosphatemia further reduces ionized calcium by complexing with phosphate.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":4}],"confusable_with":"vitamin D deficiency alone (CKD requires activated calcitriol replacement, not just ergocalciferol/cholecalciferol)"},
  {"id":"hypocalcemia-d4","topic":"Hypocalcemia","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Anesthetic-induced cardiac depression is potentiated by which electrolyte abnormality?","answer":"Hypocalcemia potentiates anesthetic-induced cardiac depression; hypocalcemia decreases myocardial contractility by impairing calcium-dependent excitation-contraction coupling.","rationale":"Calcium is required for actin-myosin interaction during myocardial contraction; hypocalcemia reduces contractility, which is compounded by the negative inotropic effects of volatile anesthetics.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":571}],"confusable_with":"hypomagnesemia (also impairs cardiac function but through different mechanism)"},
  {"id":"hypocalcemia-d5","topic":"Hypocalcemia","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Hypocalcemia following rhabdomyolysis has what mechanism and what paradox occurs during recovery?","answer":"Calcium precipitates in injured muscle (sequestration), causing hypocalcemia acutely; during recovery, mobilization of calcium from muscle deposits causes hypercalcemia.","rationale":"Muscle injury releases phosphate that complexes with calcium, depositing as calcium phosphate in damaged tissue; as repair occurs, these deposits resolubilize.","bloom":"analyze","source":[{"book":"Morgan & Mikhail","page":1892}],"confusable_with":"AKI as the primary cause of hypocalcemia in rhabdomyolysis (both contribute; calcium sequestration in muscle is the additional mechanism)"},
  {"id":"hypocalcemia-d6","topic":"Hypocalcemia","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Pseudohypoparathyroidism (PHP) causes hypocalcemia, hyperphosphatemia, and high PTH. What is its molecular mechanism?","answer":"PHP type 1 is caused by end-organ resistance to PTH action; mutations in the GNAS gene reduce Gs alpha protein function, impairing cAMP signaling downstream of the PTH receptor.","rationale":"PTH binds its receptor but cannot activate the intracellular signaling cascade adequately; the kidney fails to excrete phosphate or reabsorb calcium, causing hypoparathyroid-like biochemistry despite high PTH.","bloom":"analyze","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":4}],"confusable_with":"true hypoparathyroidism (both cause hypocalcemia + hyperphosphatemia, but PHP has elevated PTH with resistance)"}
]

kps.append({"_type":"illness_script","topic":"Hypocalcemia","discipline":"medicine","enabling_conditions":"Post-thyroidectomy/parathyroidectomy, CKD, hypomagnesemia, pancreatitis, massive transfusion, vitamin D deficiency, PHP","pathophysiology":"Insufficient PTH, impaired vitamin D activation, or calcium sequestration reduces ionized calcium; alkalosis further lowers ionized calcium; membrane excitability increases","time_course":"Acute: post-surgical (hours); chronic: CKD, vitamin D deficiency (weeks to months)","key_features":"Perioral numbness, Chvostek/Trousseau signs, tetany, prolonged QT on ECG, ionized Ca <1.1 mmol/L","consequence_if_missed":"Laryngospasm, seizures, cardiac arrhythmias, respiratory arrest; anesthetic cardiac depression amplified"})

# 152: Hypocalcemia causes and management
kps += [
  {"id":"hypocalcemia-management-d1","topic":"Hypocalcemia: Causes and Management","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Which electrolyte must be corrected before treating hypocalcemia, and why?","answer":"Hypomagnesemia must be corrected first; magnesium deficiency impairs PTH secretion and creates end-organ resistance to PTH, preventing calcium correction.","rationale":"Magnesium is required for PTH release from parathyroid cells and for PTH receptor signaling in target organs; untreated hypomagnesemia makes hypocalcemia refractory to calcium replacement.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":8}],"confusable_with":"repleting calcium first (without magnesium correction, hypocalcemia will not resolve in hypomagnesemic patients)"},
  {"id":"hypocalcemia-management-d2","topic":"Hypocalcemia: Causes and Management","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"How is calcium homeostasis regulated by PTH, calcitriol, and FGF23?","answer":"PTH increases calcium (bone resorption, renal reabsorption, calcitriol synthesis); calcitriol increases intestinal Ca absorption; FGF23 from osteocytes reduces calcitriol production and increases phosphaturia; the calcium-sensing receptor (CaSR) provides feedback to parathyroid cells.","rationale":"These three hormones form a regulatory network; PTH responds within minutes to ionized calcium changes while calcitriol and FGF23 regulate on a longer timescale through genomic mechanisms.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":2}],"confusable_with":"calcitonin as a primary calcium regulator (relatively minor role in adult calcium homeostasis compared with PTH and calcitriol)"},
  {"id":"hypocalcemia-management-d3","topic":"Hypocalcemia: Causes and Management","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Cinacalcet is a calcimimetic used in primary and secondary hyperparathyroidism. What calcium abnormality can it cause?","answer":"Cinacalcet stimulates the calcium-sensing receptor (CaSR), suppressing PTH secretion; the resulting decrease in PTH can cause hypocalcemia.","rationale":"By activating CaSR, cinacalcet mimics high calcium to parathyroid cells, reducing PTH secretion; if PTH falls excessively, calcium homeostasis is impaired.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":5}],"confusable_with":"hypercalcemia from cinacalcet (it treats hypercalcemia; hypocalcemia is the potential adverse effect)"},
  {"id":"hypocalcemia-management-d4","topic":"Hypocalcemia: Causes and Management","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Hypocalcemia in CKD is best treated with which vitamin D formulation and why?","answer":"Activated vitamin D (calcitriol) is required in CKD since impaired renal 1-alpha-hydroxylase prevents activation of vitamin D precursors; ergocalciferol may also be given if 25-OH vitamin D is deficient but calcitriol is the definitive replacement.","rationale":"CKD patients cannot hydroxylate 25-OH vitamin D to calcitriol; providing the pre-activated form bypasses the deficient renal enzyme step.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":8}],"confusable_with":"ergocalciferol/cholecalciferol alone in CKD (requires renal activation; ineffective without calcitriol supplementation in advanced CKD)"},
  {"id":"hypocalcemia-management-d5","topic":"Hypocalcemia: Causes and Management","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Bisphosphonates and denosumab used for osteoporosis can cause hypocalcemia through what mechanism, and what should be corrected first?","answer":"These agents reduce bone resorption, decreasing calcium mobilization from bone; concomitant vitamin D deficiency worsens hypocalcemia; vitamin D and calcium levels should be corrected before initiating treatment.","rationale":"Bisphosphonates and denosumab suppress osteoclast activity; without adequate vitamin D and calcium stores, they can unmask or worsen hypocalcemia, particularly post-parathyroidectomy.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":5}],"confusable_with":"bisphosphonate-induced hypercalcemia (bisphosphonates lower calcium; PTHrP-associated hypercalcemia responds to them)"},
  {"id":"hypocalcemia-management-d6","topic":"Hypocalcemia: Causes and Management","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Approximately what percentage of the body's calcium is protein-bound, and what is the clinical significance?","answer":"Approximately 45% of circulating calcium is protein-bound (mainly to albumin); this fraction is not biologically active; only ionized calcium (about 50%) is physiologically active.","rationale":"Albumin fluctuations alter total calcium without changing ionized fraction; albumin correction or direct ionized calcium measurement is required for accurate assessment.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypocalcemia  Causes and Management","page":2}],"confusable_with":"total serum calcium as the definitive measure (ionized calcium is the physiologically relevant fraction)"}
]

kps.append({"_type":"illness_script","topic":"Hypocalcemia: Causes and Management","discipline":"medicine","enabling_conditions":"Post-thyroidectomy/parathyroidectomy, CKD, hypomagnesemia, pancreatitis, vitamin D deficiency, PHP, bisphosphonate/cinacalcet use, massive transfusion","pathophysiology":"Insufficient PTH, impaired vitamin D activation, calcium sequestration, or drug-induced PTH suppression reduces ionized calcium; alkalosis worsens ionized deficiency","time_course":"Acute: post-surgical (hours); drug-induced: days to weeks; CKD: chronic","key_features":"Perioral/fingertip numbness, Chvostek/Trousseau signs, prolonged QT, muscle cramps, ionized Ca <1.1 mmol/L","consequence_if_missed":"Laryngospasm, seizures, cardiac arrhythmias; refractory if hypomagnesemia not corrected first"})

# 153: Hypomagnesemia
kps += [
  {"id":"hypomagnesemia-d1","topic":"Hypomagnesemia: Causes and Consequences","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"What serum magnesium level defines hypomagnesemia and what are the most serious clinical consequences?","answer":"Hypomagnesemia: serum Mg <1.46 mg/dL (<0.6 mmol/L); consequences range from mild tremors and weakness to cardiac ischemia and death.","rationale":"Magnesium is essential for over 300 enzymatic reactions; severe deficiency impairs neuromuscular transmission, cardiac conduction, and PTH secretion.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypomagnesemia  Causes and Consequences","page":1}],"confusable_with":"hypermagnesemia (opposite direction; causes hyporeflexia, respiratory depression)"},
  {"id":"hypomagnesemia-d2","topic":"Hypomagnesemia: Causes and Consequences","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Gitelman syndrome causes hypomagnesemia through what renal tubular mechanism?","answer":"Gitelman syndrome: mutation in SLC12A3 (thiazide-sensitive NaCl cotransporter in DCT) impairs Mg reabsorption in DCT, causing hypomagnesemia; also causes hypocalciuria (increased Ca reabsorption) and secondary hypokalemia via RAAS activation.","rationale":"The DCT-specific transporter defect in Gitelman syndrome creates selective Mg and NaCl wasting; the compensatory calcium reabsorption explains the characteristic hypocalciuria.","bloom":"analyze","source":[{"book":"StatPearls: StatPearls   Hypomagnesemia  Causes and Consequences","page":4}],"confusable_with":"Bartter syndrome (different tubular segment and transporter; hypercalciuria rather than hypocalciuria)"},
  {"id":"hypomagnesemia-d3","topic":"Hypomagnesemia: Causes and Consequences","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"How can hypomagnesemia and hypokalemia be distinguished as gastrointestinal versus renal losses?","answer":"Measure 24-hour urine magnesium or spot FEMg (fractional excretion); renal losses: inappropriately high urine Mg (>24 mg/24h or FEMg >2%); GI losses: low urine Mg as the kidney appropriately conserves.","rationale":"The kidney is the main regulator of magnesium; in GI loss states, the kidney maximally conserves magnesium; inappropriately high urine magnesium implicates renal wasting.","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypomagnesemia  Causes and Consequences","page":6}],"confusable_with":"using serum Mg alone to identify the site of loss (serum level does not distinguish GI from renal etiology)"},
  {"id":"hypomagnesemia-d4","topic":"Hypomagnesemia: Causes and Consequences","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"What common medication class causes renal magnesium wasting as a well-known side effect?","answer":"Proton pump inhibitors (PPIs) cause hypomagnesemia through impaired intestinal magnesium absorption; this is often underrecognized but occurs with chronic PPI use (prevalence ~0.4-11%).","rationale":"PPIs alter gut pH and reduce TRPM6/7 channel expression in intestinal epithelium, impairing active magnesium absorption; IV replacement may be needed if oral correction fails with continued PPI use.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypomagnesemia  Causes and Consequences","page":3}],"confusable_with":"diuretic-induced hypomagnesemia (loop/thiazide diuretics cause renal losses; PPI effect is intestinal)"},
  {"id":"hypomagnesemia-d5","topic":"Hypomagnesemia: Causes and Consequences","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Alcohol use disorder has what reported prevalence of hypomagnesemia, and what are the key mechanisms?","answer":"Approximately 30% prevalence in alcohol use disorder; mechanisms include poor dietary intake, GI malabsorption, renal tubular magnesium wasting (aldosterone activation from volume depletion), and vomiting.","rationale":"Alcohol is the most common cause of hypomagnesemia; multiple simultaneous mechanisms deplete magnesium stores, which can be difficult to replicate in routine laboratory measurements.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypomagnesemia  Causes and Consequences","page":2}],"confusable_with":"assuming hypomagnesemia in alcohol use disorder is only from malnutrition (renal wasting is an independent mechanism)"},
  {"id":"hypomagnesemia-d6","topic":"Hypomagnesemia: Causes and Consequences","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Why must magnesium supplementation dose be reduced in patients with creatinine clearance <30 mL/min?","answer":"These patients are at risk for hypermagnesemia; guidelines recommend reducing the magnesium dose by 50% and closely monitoring serum levels, as the kidney cannot excrete excess magnesium.","rationale":"Magnesium is primarily renally excreted; in severe CKD, magnesium accumulates rapidly causing toxicity (loss of deep tendon reflexes, respiratory paralysis, cardiac arrest).","bloom":"apply","source":[{"book":"StatPearls: StatPearls   Hypomagnesemia  Causes and Consequences","page":6}],"confusable_with":"using standard dosing in CKD patients (risk of life-threatening hypermagnesemia with standard doses)"}
]

kps.append({"_type":"illness_script","topic":"Hypomagnesemia: Causes and Consequences","discipline":"medicine","enabling_conditions":"Alcohol use disorder (30%), PPIs, loop/thiazide diuretics, Gitelman syndrome, post-ATN diuresis, malabsorption, DKA treatment","pathophysiology":"Renal or GI losses deplete Mg stores; Mg deficiency impairs PTH secretion/action (causing hypocalcemia), K+ retention (causing hypokalemia), and cardiac conduction","time_course":"Chronic in malabsorption/alcoholism; acute post-ATN recovery or DKA treatment","key_features":"Serum Mg <1.46 mg/dL; coexisting hypocalcemia and hypokalemia; tremors, arrhythmias (TdP); ECG changes similar to hypokalemia","consequence_if_missed":"Refractory hypokalemia/hypocalcemia until magnesium corrected; cardiac arrhythmias (torsades de pointes); seizures"})

# 154: Hypophosphatemia
kps += [
  {"id":"hypophosphatemia-d1","topic":"Hypophosphatemia: Causes and Clinical Impact","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"What serum phosphate level does hypophosphatemia become symptomatic, and what is the prevalence in ICU patients?","answer":"Symptoms typically appear below 1 mg/dL (0.32 mmol/L); present in 29-34% of ICU patients and up to 80% in DKA, alcoholism, or sepsis.","rationale":"Phosphate is essential for ATP generation; severe depletion impairs cellular energy production across every organ system, causing multi-system dysfunction.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypophosphatemia  Causes and Clinical Impact","page":3}],"confusable_with":"mild asymptomatic hypophosphatemia (2.0-2.5 mg/dL) which is common and does not require urgent treatment"},
  {"id":"hypophosphatemia-d2","topic":"Hypophosphatemia: Causes and Clinical Impact","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Severe hypophosphatemia is associated with a how many-fold increase in mortality?","answer":"Severe hypophosphatemia is associated with an approximately four-fold increase in mortality.","rationale":"ATP depletion impairs cardiac contractility, respiratory muscle function, erythrocyte oxygen delivery (2,3-DPG depletion), and immune function, collectively contributing to excess mortality.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypophosphatemia  Causes and Clinical Impact","page":3}],"confusable_with":"mild hypophosphatemia (2-2.5 mg/dL) which is associated with minimal morbidity"},
  {"id":"hypophosphatemia-d3","topic":"Hypophosphatemia: Causes and Clinical Impact","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"How does acute respiratory alkalosis cause hypophosphatemia?","answer":"Respiratory alkalosis increases pH, stimulating phosphofructokinase and glycolysis, consuming phosphate intracellularly to generate ATP; serum phosphate shifts intracellularly; extreme hyperventilation (PaCO2 <20 mmHg) can cause severe hypophosphatemia.","rationale":"The alkalotic pH activates glycolytic enzymes that rapidly consume inorganic phosphate; this is the mechanism in pain-induced hyperventilation, mechanical over-ventilation, and refeeding syndrome.","bloom":"analyze","source":[{"book":"StatPearls: StatPearls   Hypophosphatemia  Causes and Clinical Impact","page":5}],"confusable_with":"metabolic alkalosis (also shifts phosphate intracellularly but generally less dramatic than acute respiratory alkalosis)"},
  {"id":"hypophosphatemia-d4","topic":"Hypophosphatemia: Causes and Clinical Impact","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"What are the musculoskeletal consequences of prolonged severe hypophosphatemia?","answer":"Generalized muscular weakness (ATP depletion), rhabdomyolysis (intracellular ATP depletion and mitochondrial dysfunction), osteopenia/osteoporosis/rickets/osteomalacia from decreased bone mineralization, increased fracture risk.","rationale":"Phosphate is essential for bone matrix mineralization (hydroxyapatite) and ATP production in muscle; prolonged deficiency depletes both structural and functional phosphate pools.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypophosphatemia  Causes and Clinical Impact","page":7}],"confusable_with":"calcium deficiency causing similar bone pathology (X-linked hypophosphatemic rickets is phosphate-specific, not calcium-driven)"},
  {"id":"hypophosphatemia-d5","topic":"Hypophosphatemia: Causes and Clinical Impact","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"X-linked hypophosphatemic rickets (XLH) and tumor-induced osteomalacia (TIO) both cause hypophosphatemia through what shared mechanism?","answer":"Both cause overproduction of FGF23: XLH from PHEX gene mutations; TIO from paraneoplastic FGF23 overproduction by mesenchymal tumors; excess FGF23 promotes phosphaturia and suppresses calcitriol.","rationale":"FGF23 is the master phosphaturic hormone; PHEX normally degrades FGF23; PHEX mutations in XLH allow FGF23 accumulation; tumor cells in TIO ectopically secrete FGF23.","bloom":"analyze","source":[{"book":"StatPearls: StatPearls   Hypophosphatemia  Causes and Clinical Impact","page":4}],"confusable_with":"Fanconi syndrome (broader proximal tubule dysfunction including phosphate wasting, but not FGF23-mediated)"},
  {"id":"hypophosphatemia-d6","topic":"Hypophosphatemia: Causes and Clinical Impact","domain":"Internal medicine: nephrology, fluids & electrolytes","discipline":"medicine","stem":"Phosphate plays what fundamental role in cellular function beyond bone mineralization?","answer":"Phosphate is a component of ATP (energy currency), phospholipid cell membranes (structural), DNA/RNA backbone, and acts as an on/off switch for protein regulation via phosphorylation/dephosphorylation; it is essential for nearly all cellular function.","rationale":"The widespread roles of phosphate explain why severe hypophosphatemia can affect every organ system simultaneously.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Hypophosphatemia  Causes and Clinical Impact","page":2}],"confusable_with":"magnesium deficiency (also affects ATP production and enzymatic function, but through different mechanisms)"}
]

kps.append({"_type":"illness_script","topic":"Hypophosphatemia: Causes and Clinical Impact","discipline":"medicine","enabling_conditions":"Refeeding syndrome, DKA treatment, alcoholism, respiratory alkalosis, malabsorption, antacid use (aluminum/magnesium binding), FGF23-excess (XLH, TIO)","pathophysiology":"Reduced GI absorption, increased renal wasting, or intracellular shift depletes phosphate; ATP depletion affects muscle, RBC, respiratory, and cardiac function","time_course":"Acute: refeeding (24-72h), DKA treatment, respiratory alkalosis; chronic: malabsorption, FGF23-excess conditions","key_features":"Muscle weakness, rhabdomyolysis, hemolysis (2,3-DPG depletion), bone pain; serum phosphate <2.5 mg/dL (<1 mg/dL for severe symptoms","consequence_if_missed":"Respiratory failure from diaphragm weakness, cardiac arrhythmias, rhabdomyolysis-AKI, refeeding syndrome in malnourished patients started on nutrition"})

# 155: Hypothyroidism
kps += [
  {"id":"hypothyroidism-d1","topic":"Hypothyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"How is primary hypothyroidism distinguished from secondary (central) hypothyroidism by laboratory testing?","answer":"Primary hypothyroidism: elevated TSH + low free T4; secondary/central: low TSH + low free T4 (pituitary failure); TSH alone is inadequate in suspected central hypothyroidism.","rationale":"In primary hypothyroidism, the pituitary responds to low T4 with TSH elevation; in central disease, the pituitary itself is damaged and cannot produce TSH.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":1228}],"confusable_with":"euthyroid sick syndrome (low T3, variable T4, low/normal/elevated TSH; does not indicate true hypothyroidism)"},
  {"id":"hypothyroidism-d2","topic":"Hypothyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Myxedema coma is the extreme form of hypothyroidism. What are its key clinical features?","answer":"Myxedema coma: extreme hypothyroidism presenting with coma, hypothermia, hypoventilation, hypotension, bradycardia, hyponatremia, and hypoglycemia; precipitated by infection, cold exposure, or anesthetic drugs.","rationale":"Severe thyroid hormone deficiency impairs thermogenesis, CO2 responsiveness, cardiac output, ADH regulation, and gluconeogenesis, causing multi-system failure.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":1228}],"confusable_with":"hypothyroidism-induced delayed emergence from anesthesia (myxedema coma has more severe multi-system involvement)"},
  {"id":"hypothyroidism-d3","topic":"Hypothyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What anesthetic induction agent can be used when coexisting primary adrenal insufficiency is suspected with severe hypothyroidism, and why?","answer":"Ketamine or etomidate; coexisting adrenal insufficiency causes refractory hypotension, reduced intravascular volume, and impaired stress response; etomidate is hemodynamically neutral; ketamine supports blood pressure through sympathomimetic effects.","rationale":"Primary hypothyroidism (e.g., autoimmune thyroiditis) may coexist with autoimmune adrenal insufficiency (Schmidt syndrome); refractory hypotension under anesthesia may indicate cortisol deficiency requiring stress-dose steroids.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":1229}],"confusable_with":"using propofol in severe hypothyroidism (causes profound hypotension if adrenal insufficiency is coexisting)"},
  {"id":"hypothyroidism-d4","topic":"Hypothyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Thyroid hormone replacement takes how long to produce physiological effect, and what coexisting condition should be ruled out before aggressive hormone replacement?","answer":"Oral thyroid hormone replacement takes several days for effect and several weeks to normalize TSH; coexisting primary adrenal insufficiency must be excluded/treated first, as thyroid hormone increases cortisol metabolism and can precipitate adrenal crisis.","rationale":"Thyroid hormone accelerates cortisol clearance; in adrenal insufficiency, thyroid replacement without concurrent glucocorticoid replacement can precipitate an Addisonian crisis.","bloom":"analyze","source":[{"book":"Morgan & Mikhail","page":1228}],"confusable_with":"starting full-dose thyroid replacement immediately (dangerous in elderly or with adrenal insufficiency; gradual titration is standard)"},
  {"id":"hypothyroidism-d5","topic":"Hypothyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What airway complication specific to hypothyroidism may complicate laryngoscopy and intubation?","answer":"Macroglossia (large tongue from myxedematous infiltration) and potential airway compression from large goiter can make laryngoscopy difficult; recurrent laryngeal nerve palsy from large goiters can cause hoarseness or stridor.","rationale":"Myxedematous infiltration of soft tissues causes tongue enlargement; goiter can displace or compress the trachea, requiring careful airway assessment.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":1229}],"confusable_with":"tracheal deviation from any goiter (airway displacement is not specific to hypothyroid state, but soft tissue infiltration is)"},
  {"id":"hypothyroidism-d6","topic":"Hypothyroidism","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What inpatient thyroid function testing strategy is recommended when thyroid disease is clinically suspected?","answer":"Test TSH + FT4 + T3 (not TSH alone); TSH reflects changes over 4-6 weeks; undetectable TSH (<0.01) suggests true hyperthyroidism; TSH >20 + low T4 suggests true hypothyroidism; routine screening on all hospital admissions is not indicated.","rationale":"Euthyroid sick syndrome in critically ill patients causes low T3 and variable T4/TSH without true thyroid disease; targeted testing only when clinically indicated prevents overdiagnosis.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":189}],"confusable_with":"ordering TSH alone (misses secondary hypothyroidism and does not distinguish euthyroid sick from true hypothyroidism in sick patients)"}
]

kps.append({"_type":"illness_script","topic":"Hypothyroidism","discipline":"medicine","enabling_conditions":"Autoimmune thyroiditis (Hashimoto), post-radioiodine ablation, post-thyroidectomy, iodine deficiency, amiodarone, lithium","pathophysiology":"Insufficient T3/T4 reduces metabolic rate, thermogenesis, cardiac output, and GI motility; TSH rises (primary) or falls (secondary) accordingly; myxedematous infiltration affects skin, tongue, pericardium","time_course":"Subclinical (elevated TSH, normal FT4) to overt; myxedema coma is a decompensated extreme precipitated by stress","key_features":"Fatigue, cold intolerance, weight gain, constipation, bradycardia, delayed relaxation of DTRs, dry skin; elevated TSH + low FT4","consequence_if_missed":"Myxedema coma (mortality 30-60%); perioperative hemodynamic collapse; adrenal crisis if thyroid replacement started without glucocorticoid coverage"})

